impl Solution {
    pub fn min_operations(nums: Vec<i32>) -> i32 {
        if nums.is_empty() {
            return 0;
        }

        let mut operations = 0;
        let mut prev = nums[0];

        for &num in nums.iter().skip(1) {
            if num <= prev {
                operations += prev + 1 - num;
                prev += 1;
            } else {
                prev = num;
            }
        }

        operations
    }
}

